package com.badrulamin.University_Management.controller;  import com.badrulamin.University_Management.entity.FacultyDivision; import com.badrulamin.University_Management.service.FacultyDivisionService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.badrulamin.University_Management.payload.response.PagedResponse; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.data.domain.Sort;  @RestController @RequestMapping("/api/faculty-divisions") @RequiredArgsConstructor public class FacultyDivisionController {      private final FacultyDivisionService facultyDivisionService;      @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     @GetMapping     public ResponseEntity<PagedResponse<FacultyDivision>> findAll(             @RequestParam(defaultValue = "0") int page,             @RequestParam(defaultValue = "20") int size,             @RequestParam(defaultValue = "id") String sortBy,             @RequestParam(defaultValue = "asc") String sortDir) {         Sort sort = sortDir.equalsIgnoreCase("desc") ? Sort.by(sortBy).descending() : Sort.by(sortBy).ascending();         Pageable pageable = PageRequest.of(page, size, sort);         Page<FacultyDivision> paged = facultyDivisionService.findAll(pageable);         PagedResponse<FacultyDivision> response = new PagedResponse<>(paged.getContent(), paged.getNumber(), paged.getSize(), paged.getTotalElements(), paged.getTotalPages(), paged.isFirst(), paged.isLast());         return ResponseEntity.ok(response);     }      @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     @GetMapping("/{id}")     public ResponseEntity<FacultyDivision> findById(@PathVariable Long id) {         return ResponseEntity.ok(facultyDivisionService.findById(id));     }      @PreAuthorize("hasAuthority('ACADEMIC_MANAGE')")     @PostMapping     public ResponseEntity<FacultyDivision> save(@Valid @RequestBody FacultyDivision facultyDivision) {         return ResponseEntity.ok(facultyDivisionService.save(facultyDivision));     }      @PreAuthorize("hasAuthority('ACADEMIC_MANAGE')")     @PutMapping("/{id}")     public ResponseEntity<FacultyDivision> update(@PathVariable Long id, @Valid @RequestBody FacultyDivision facultyDivision) {         return ResponseEntity.ok(facultyDivisionService.update(id, facultyDivision));     }      @PreAuthorize("hasAuthority('ACADEMIC_MANAGE')")     @DeleteMapping("/{id}")     public ResponseEntity<Void> delete(@PathVariable Long id) {         facultyDivisionService.delete(id);         return ResponseEntity.noContent().build();     } }